class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  public void flatten(TreeNode root) {
    TreeNode cur = root;
    while (cur != null) {
      if (cur.left != null) {
        TreeNode prev = cur.left;
        while (prev.right != null) prev = prev.right;
        prev.right = cur.right;
        cur.right = cur.left;
        cur.left = null;
      }
      cur = cur.right;
    }
  }
}

class Solution:
    def flatten(self, root: Optional[TreeNode]) -> None:
        cur = root
        while cur:
            if cur.left:
                prev = cur.left
                while prev.right:
                    prev = prev.right
                prev.right = cur.right
                cur.right = cur.left
                cur.left = None
            cur = cur.right

impl Solution {
  pub fn flatten(root: &mut Option<Box<TreeNode>>) {
    if root.is_none() {
      return;
    }
    let mut node = root.take().unwrap();
    Self::flatten(&mut node.left);
    Self::flatten(&mut node.right);
    let left = node.left.take();
    let right = node.right.take();
    if left.is_some() {
      node.right = left;
      let mut tail = node.right.as_mut().unwrap();
      while tail.right.is_some() {
        tail = tail.right.as_mut().unwrap();
      }
      tail.right = right;
    } else {
      node.right = right;
    }
    node.left = None;
    *root = Some(node);
  }
}

const flatten = (root: TreeNode | null): void => {
  let cur = root;
  while (cur) {
    if (cur.left) {
      let prev = cur.left;
      while (prev.right) prev = prev.right;
      prev.right = cur.right;
      cur.right = cur.left;
      cur.left = null;
    }
    cur = cur.right;
  }
};
